@page "/dashboard"
@using sv_d8be11d1e8ae4350b19f75b60a514bf4.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p class="lead">
    Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong>
</p>

<div class="card mt-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum level:
            <span class="badge @BadgeClass fs-5">@AlertService.LatestLowStockCount</span>
        </p>
        <p class="text-muted small">Refreshes every 10 seconds while this page is visible.</p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    private string BadgeClass => AlertService.LatestLowStockCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        _ => "bg-success"
    };

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);

        StartPolling();
    }

    private async void OnWarehouseChanged()
    {
        // Warehouse changed — refresh immediately with the new warehouse
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
        StateHasChanged();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

